#![allow(unused_imports)]
use vstd::prelude::*;

verus! {
    /// Returns `true` exactly when `n` is strictly greater than
    /// every element of the slice `a`.
    /// 
    /// Specification:
    ///   result == forall i < a.len(): n > a[i]
    fn is_greater(n: i32, a: &[i32]) -> (result: bool)
        ensures
            // result holds iff n > every element of a
            result == (forall|i: usize| i < a.len() ==> n > a[i])
    {
        let mut i: usize = 0;
        // Loop over all valid indices
        while i < a.len() {
            // Invariant: we have checked all j < i so far, and found
            // n > a[j].
            invariant i <= a.len();
            invariant forall|j: usize| j < i ==> n > a[j];
            decreases a.len() - i;

            // If the current element fails, we can return false immediately
            if !(n > a[i]) {
                // we know a[i] >= n
                assert(a[i] >= n);
                // hence it's not true that n > all a[k]
                assert(! (forall|k: usize| k < a.len() ==> n > a[k]));
                return false;
            }

            i = i + 1;
        }

        // when the loop exits, i == a.len() and the invariant
        // says n > a[j] for all j < a.len()
        assert(i == a.len());
        assert(forall|k: usize| k < a.len() ==> n > a[k]);

        // so we can safely return true
        return true;
    }
}